@staticmethod
def _copy_lifetime_evidence(evidence: object) -> object:
    """Detach one side of a change record for a lifetime transition."""
    if evidence is None:
        return None
    record: dict[str, object] = evidence  # type: ignore[assignment]
    if "cause" in record:
        return {
            "cause": record["cause"],
            "key": record["key"],
            "intervals": tuple(record["intervals"]),
            "checkpoints": tuple(record["checkpoints"]),
            "branches": tuple(record["branches"]),
            "affected": tuple(record["affected"]),
        }
    if "path" in record:
        return {
            "source": record["source"],
            "target": record["target"],
            "path": tuple(record["path"]),
        }
    return {
        "interval": record["interval"],
        "members": tuple(record["members"]),
    }

